//! FFI bridge between Swift and Rust, generated by [`swift-bridge`].
//!
//! All functions in the `#[swift_bridge::bridge] mod ffi` block are callable
//! from Swift. They follow a uniform JSON-in / JSON-out convention:
//!
//! - **Inputs**: scalar Swift types (`i64`, `u32`, `&str`) or JSON-encoded arrays.
//! - **Output**: a JSON `String` with one of two shapes:
//!   - `{"ok": <payload>}` on success
//!   - `{"error": "<message>"}` on failure
//!
//! ## Thread safety
//!
//! All global services (`PLAYER_SERVICE`, `LIBRARY_SERVICE`, `ARTWORK_SERVICE`)
//! are protected by `Mutex`. `cpal::Stream` is `!Send` on macOS; the
//! `FfiPlayerService` wrapper asserts the safety invariant that access is
//! always serialized through the `PLAYER_SERVICE` mutex so the stream never
//! crosses thread boundaries directly.

use once_cell::sync::Lazy;
use std::path::PathBuf;
use std::sync::Mutex;

use crate::db;
use crate::services::*;
use crate::utils::AppPaths;
use crate::utils::MutexExt;

// Global database pool - the only shared state we need
static DB_POOL: Lazy<Mutex<Option<db::DbPool>>> = Lazy::new(|| Mutex::new(None));

/// Bounds the unsafe surface required to make `PlayerService` usable across threads.
///
/// `AudioEngine` owns a `cpal::Stream` which is `!Send` on macOS (CoreAudio
/// requirement). `FfiPlayerService` asserts the safety invariant that all
/// access is serialized by `PLAYER_SERVICE` Mutex, so no concurrent `&PlayerService`
/// reference is ever exposed.
mod ffi_bridge {
    use super::player;

    pub struct FfiPlayerService(pub player::PlayerService);

    /// # Safety
    ///
    /// All access to `FfiPlayerService` is serialized through `PLAYER_SERVICE` Mutex.
    /// `AudioEngine` (holding the cpal Stream) never crosses thread boundaries
    /// directly — it is always accessed while holding the `PLAYER_SERVICE` lock.
    unsafe impl Send for FfiPlayerService {}

    /// # Safety
    ///
    /// Same invariant as `Send`: `PLAYER_SERVICE` Mutex ensures exclusive access;
    /// no `&PlayerService` reference is handed out across threads concurrently.
    unsafe impl Sync for FfiPlayerService {}
}

use ffi_bridge::FfiPlayerService;

// Global player service (wrapped for thread safety)
static PLAYER_SERVICE: Lazy<Mutex<Option<FfiPlayerService>>> = Lazy::new(|| Mutex::new(None));

// Global library service (for accessing scan progress)
static LIBRARY_SERVICE: Lazy<Mutex<Option<library::LibraryService>>> =
    Lazy::new(|| Mutex::new(None));

// Global artwork service
static ARTWORK_SERVICE: Lazy<Mutex<Option<artwork::ArtworkService>>> =
    Lazy::new(|| Mutex::new(None));

// Global tokio runtime for async operations
static TOKIO_RUNTIME: Lazy<tokio::runtime::Runtime> =
    Lazy::new(|| tokio::runtime::Runtime::new().expect("Failed to create tokio runtime"));

fn get_or_init_pool() -> Result<db::DbPool, String> {
    let mut pool_opt = DB_POOL.lock().unwrap();

    if pool_opt.is_none() {
        // Initialize application paths
        let app_paths =
            AppPaths::new().map_err(|e| format!("Failed to initialize app paths: {e}"))?;

        // Create database connection pool
        let pool = db::create_pool(app_paths.database_path())
            .map_err(|e| format!("Failed to create database pool: {e}"))?;

        // Initialize database schema
        db::initialize_database(&pool)
            .map_err(|e| format!("Failed to initialize database: {e}"))?;

        *pool_opt = Some(pool);
    }

    Ok(pool_opt.as_ref().unwrap().clone())
}

fn get_or_init_player() -> Result<(), String> {
    let mut player_opt = PLAYER_SERVICE.lock().unwrap();

    if player_opt.is_none() {
        // Get database pool first
        let pool = get_or_init_pool()?;

        // Create player service
        let player = player::PlayerService::new(pool)
            .map_err(|e| format!("Failed to create player service: {e}"))?;

        *player_opt = Some(FfiPlayerService(player));
    }

    Ok(())
}

fn get_or_init_library() -> Result<library::LibraryService, String> {
    let mut library_opt = LIBRARY_SERVICE.lock().unwrap();

    if library_opt.is_none() {
        // Get database pool first
        let pool = get_or_init_pool()?;

        // Initialize app paths
        let app_paths =
            AppPaths::new().map_err(|e| format!("Failed to initialize app paths: {e}"))?;

        // Create library service
        let library = library::LibraryService::new(pool, app_paths);

        *library_opt = Some(library);
    }

    Ok(library_opt.as_ref().unwrap().clone())
}

fn get_or_init_artwork() -> Result<(), String> {
    let mut artwork_opt = ARTWORK_SERVICE.lock_infallible();

    if artwork_opt.is_none() {
        // Get database pool first
        let pool = get_or_init_pool()?;

        // Initialize app paths
        let app_paths =
            AppPaths::new().map_err(|e| format!("Failed to initialize app paths: {e}"))?;

        // Create artwork service
        let artwork = artwork::ArtworkService::new(pool, app_paths);

        *artwork_opt = Some(artwork);
    }

    Ok(())
}

