    #[test]
    fn test_get_tracks_page_all_named_sort_fields_do_not_crash() {
        let env = TestEnv::new();
        env.seed_basic_library();
        for sort_by in &[
            "artist",
            "album",
            "duration",
            "track_number",
            "file_size",
            "play_count",
            "rating",
            "file_path",
            "unknown_field",
        ] {
            let ids = query_track_ids_sorted(&env.pool, sort_by, "asc");
            assert_eq!(
                ids.len(),
                2,
                "sort_by='{}' must return all seeded tracks",
                sort_by
            );
        }
    }
